pragma solidity >=0.8.0;
contract EventIdxDyn {
    event One(string indexed a);
    event Two(string indexed a, bytes indexed b);
    event Three(string indexed a, bytes indexed b, string indexed c);
    string public lastS;
    bytes public lastB;
    function burst(string memory s, bytes memory b) external {
        lastS = s;
        lastB = b;
        emit One(s);
        emit Two(s, b);
        emit Three(s, b, s);
        emit One(s);
        emit Two(s, b);
    }
    function getLast() external view returns (string memory, bytes memory) {
        return (lastS, lastB);
    }
}
